from decimal import Decimal, InvalidOperation


def _validate_grouped_int(int_raw: str, sep_chars: set) -> str:
    if int_raw == "":
        raise ValueError("empty integer part")
    has_sep = any(ch in sep_chars for ch in int_raw)
    if not has_sep:
        if not int_raw.isdigit():
            raise ValueError(f"bad integer part: {int_raw!r}")
        return int_raw
    groups = []
    cur = ""
    for ch in int_raw:
        if ch in sep_chars:
            groups.append(cur)
            cur = ""
        elif ch.isdigit():
            cur += ch
        else:
            raise ValueError(f"bad integer part: {int_raw!r}")
    groups.append(cur)
    if any(g == "" for g in groups):
        raise ValueError(f"bad thousands grouping: {int_raw!r}")
    if not (1 <= len(groups[0]) <= 3) or not groups[0].isdigit():
        raise ValueError(f"bad thousands grouping: {int_raw!r}")
    for g in groups[1:]:
        if len(g) != 3 or not g.isdigit():
            raise ValueError(f"bad thousands grouping: {int_raw!r}")
    return "".join(groups)


def parse_number(text: str) -> Decimal:
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    s = text.strip(" \t\u00a0")
    if not s:
        raise ValueError("empty input")
    negative = False
    if s.startswith("(") or s.endswith(")"):
        if not (s.startswith("(") and s.endswith(")") and len(s) >= 2):
            raise ValueError("unbalanced parentheses")
        inner = s[1:-1].strip(" \t\u00a0")
        if inner.startswith(("+", "-")):
            raise ValueError("sign cannot be combined with parentheses")
        negative = True
        s = inner
    elif s.startswith(("+", "-")):
        negative = s[0] == "-"
        s = s[1:]
    if not s:
        raise ValueError("no digits")
    if s.startswith(("+", "-")) or "(" in s or ")" in s:
        raise ValueError("misplaced sign or parenthesis")
    t = s
    if not t or any(c not in "0123456789., \u00a0" for c in t):
        raise ValueError(f"invalid characters in {text!r}")
    if not any(c.isdigit() for c in t):
        raise ValueError("no digits")
    has_dot = "." in t
    has_comma = "," in t
    SPACE_SEPS = {" ", "\u00a0"}
    if has_dot and has_comma:
        if t.rfind(".") > t.rfind(","):
            dec_sep, thou_sep = ".", ","
        else:
            dec_sep, thou_sep = ",", "."
        idx = t.rfind(dec_sep)
        int_raw = t[:idx]
        frac_raw = t[idx + 1:]
        if int_raw == "" or frac_raw == "":
            raise ValueError("bad decimal part")
        if dec_sep in int_raw:
            raise ValueError("multiple decimal separators")
        frac_nospace = frac_raw.replace(" ", "").replace("\u00a0", "")
        if not frac_nospace or not frac_nospace.isdigit():
            raise ValueError("bad decimal part")
        int_digits = _validate_grouped_int(int_raw, set(SPACE_SEPS) | {thou_sep})
        normalized = f"{int_digits}.{frac_nospace}"
    elif has_comma:
        if t.count(",") > 1:
            int_digits = _validate_grouped_int(t, set(SPACE_SEPS) | {","})
            normalized = int_digits
        else:
            idx = t.find(",")
            int_raw = t[:idx]
            frac_raw = t[idx + 1:]
            if int_raw == "" or frac_raw == "":
                raise ValueError("bad comma decimal")
            frac_nospace = frac_raw.replace(" ", "").replace("\u00a0", "")
            if not frac_nospace or not frac_nospace.isdigit():
                raise ValueError("bad comma decimal")
            int_digits = _validate_grouped_int(int_raw, set(SPACE_SEPS))
            normalized = f"{int_digits}.{frac_nospace}"
    elif has_dot:
        if t.count(".") > 1:
            int_digits = _validate_grouped_int(t, set(SPACE_SEPS) | {"."})
            normalized = int_digits
        else:
            idx = t.find(".")
            int_raw = t[:idx]
            frac_raw = t[idx + 1:]
            if int_raw == "" or frac_raw == "":
                raise ValueError("bad dot decimal")
            frac_nospace = frac_raw.replace(" ", "").replace("\u00a0", "")
            if not frac_nospace or not frac_nospace.isdigit():
                raise ValueError("bad dot decimal")
            int_digits = _validate_grouped_int(int_raw, set(SPACE_SEPS))
            normalized = f"{int_digits}.{frac_nospace}"
    else:
        int_digits = _validate_grouped_int(t, set(SPACE_SEPS))
        normalized = int_digits
    try:
        value = Decimal(normalized)
    except InvalidOperation:
        raise ValueError(f"invalid number: {text!r}") from None
    return -value if negative else value

